def maximumCandies(candies, k):
    # Helper: can we serve at least k kids with x candies each?
    def canGive(x):
        count = 0
        for pile in candies:
            count += pile // x
        return count >= k

    left, right = 1, max(candies)
    answer = 0

    while left <= right:
        mid = left + (right - left) // 2
        if canGive(mid):
            answer = mid    # feasible, try for bigger m
            left = mid + 1
        else:
            right = mid - 1
    return answer
